if product_ids is not None:
        product_ids = product_ids.split(',')
        product_ids = [int(pid.strip()) for pid in product_ids if pid.strip()]
    else:
        product_ids = []

    if not product_ids:
        return None

    criteria = []
    for pid in product_ids:
        criteria.append(('product_id', 'eq', pid))

    found = self._store.select(self.ENTITY, criteria)
    if not found:
        return None

    for record in found:
        patch = {'stock_quantity': stock_quantity}
        if stock_quantity is not None and stock_quantity < 0:
            raise ValueError(f"Product.stock_quantity must be >= 0, got {stock_quantity!r}")
        self._store.update(self.ENTITY, self.PK, record[self.PK], patch)
